def test_the_three_failure_paths_show_more_than_twenty_lines(self):
    for name in ("post-implement.sh", "pre-push.sh"):
        text = (HOOKS / name).read_text(encoding="utf-8")
        failure_tails = re.findall(r'echo "\$output" \| tail -(\d+)', text)
        assert failure_tails, name
        for n in failure_tails:
            assert int(n) >= 60 or int(n) <= 5, (
                f"{name}: `tail -{n}` on a failure path truncates past the "
                "root cause (a short tail is only for the SUCCESS summary)")
